function useFetch<T>(url: string) {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    let cancelled = false;
    fetch(url)
      .then(r => r.json())
      .then(d => !cancelled && setData(d))
      .catch(e => !cancelled && setError(e))
      .finally(() => !cancelled && setLoading(false));

    return () => { cancelled = true; }; // Cleanup
  }, [url]);

  return { data, loading, error };
}

// Uso
const { data: exercises } = useFetch('/api/exercises');

❌ Race condition
useEffect(() => {
  fetchExercises(query).then(setResults);
}, [query]);
// User digita 'a' (fetch lento), depois 'ab' (fetch rápido)
// 'ab' chega ANTES de 'a', results fica incorreto

✅ Solução: cleanup
useEffect(() => {
  let cancelled = false;
  const search = async () => {
    const data = await fetchExercises(query);
    if (!cancelled) setResults(data);
  };
  search();
  return () => { cancelled = true; }; // Cancela anterior
}, [query]);

function TeacherDashboard() {
  const [students, setStudents] = useState([]);

  const handleUpdate = useCallback((id, data) => {
    setStudents(s => s.map(st => st.id === id ? { ...st, ...data } : st));
  }, []); // Callback é estável

  return (
    <StudentList students={students} onUpdate={handleUpdate} />
  ); // StudentList é memoized, não re-renderiza
}

